<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue'
import { api, type Exam, type KnowledgePoint, type Paper, type Question, type Submission, type User } from './api'

const token = ref(localStorage.getItem('examToken') ?? '')
const user = ref<User | null>(JSON.parse(localStorage.getItem('examUser') ?? 'null') as User | null)
const username = ref('teacher'), password = ref('ExamDemo123!'), error = ref(''), busy = ref(false)
const points = ref<KnowledgePoint[]>([]), questions = ref<Question[]>([]), pointName = ref('')
const filters = reactive({ type: '', difficulty: '', knowledgePointId: '' })
const form = reactive({ type: 'SINGLE_CHOICE', stem: '', difficulty: 'MEDIUM', suggestedScore: 10,
  knowledgePointId: '', optionsText: 'A|选项 A\nB|选项 B', answer: 'A', explanation: '' })
const isTeacher = computed(() => user.value?.role === 'TEACHER')
const isStudent = computed(() => user.value?.role === 'STUDENT')
const section = ref<'bank' | 'papers' | 'exams'>('bank')
const papers = ref<Paper[]>([]), exams = ref<Exam[]>([]), selectedQuestions = ref<number[]>([])
const paperForm = reactive({ name: 'Java 基础测试', durationMinutes: 30, totalScore: 40 })
const now = new Date(), later = new Date(Date.now() + 60 * 60 * 1000)
const examForm = reactive({ name: 'Java 在线考试', paperId: '', startAt: now.toISOString().slice(0, 16), endAt: later.toISOString().slice(0, 16) })
const submission = ref<Submission | null>(null), studentAnswers = reactive<Record<number, string | boolean | string[]>>({}), resultMessage = ref('')
const clock = ref(Date.now()), activeExam = computed(() => exams.value.find(item => item.id === submission.value?.examId))
const remaining = computed(() => { const seconds = Math.max(0, Math.floor((new Date(activeExam.value?.endAt ?? 0).getTime() - clock.value) / 1000)); return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}` })
const clockTimer = window.setInterval(() => { clock.value = Date.now() }, 1000)
const types: Record<string, string> = { SINGLE_CHOICE: '单选题', MULTIPLE_CHOICE: '多选题', TRUE_FALSE: '判断题', SHORT_ANSWER: '简答题' }
const difficulties: Record<string, string> = { EASY: '简单', MEDIUM: '中等', HARD: '困难' }

async function login() {
  error.value = ''; busy.value = true
  try { const result = await api.login(username.value, password.value); token.value = result.accessToken; user.value = result.user
    localStorage.setItem('examToken', token.value); localStorage.setItem('examUser', JSON.stringify(user.value)); await loadWorkspace()
  } catch (reason) { error.value = (reason as Error).message } finally { busy.value = false }
}
async function logout() { try { if (token.value) await api.logout(token.value) } finally { token.value = ''; user.value = null; localStorage.removeItem('examToken'); localStorage.removeItem('examUser') } }
async function loadBank() {
  if (!token.value) return
  try { points.value = await api.points(token.value); const query = new URLSearchParams()
    Object.entries(filters).forEach(([key, value]) => { if (value) query.set(key, value) }); questions.value = (await api.questions(token.value, query)).items
    if (!form.knowledgePointId && points.value[0]) form.knowledgePointId = String(points.value[0].id)
  } catch (reason) { error.value = (reason as Error).message }
}
async function addPoint() { if (!pointName.value.trim()) return; try { const point = await api.createPoint(token.value, pointName.value.trim()); pointName.value = ''; points.value.push(point); form.knowledgePointId = String(point.id) } catch (reason) { error.value = (reason as Error).message } }
function answer() { if (form.type === 'TRUE_FALSE') return form.answer.trim().toLowerCase() === 'true'; if (form.type === 'SHORT_ANSWER') return form.answer.trim(); return form.answer.split(',').map(v => v.trim().toUpperCase()).filter(Boolean) }
function options() { if (!form.type.includes('CHOICE')) return []; return form.optionsText.split('\n').filter(Boolean).map(line => { const [key, ...content] = line.split('|'); return { key: key?.trim(), content: content.join('|').trim() } }) }
async function addQuestion() { error.value = ''; try { await api.createQuestion(token.value, { type: form.type, stem: form.stem, difficulty: form.difficulty, standardAnswer: answer(), explanation: form.explanation, suggestedScore: form.suggestedScore, knowledgePointId: Number(form.knowledgePointId), options: options() }); form.stem = ''; await loadBank() } catch (reason) { error.value = (reason as Error).message } }
async function removeQuestion(id: number) { if (!window.confirm('确认删除这道题吗？')) return; try { await api.deleteQuestion(token.value, id); await loadBank() } catch (reason) { error.value = (reason as Error).message } }
async function loadWorkspace() { if (isTeacher.value) { await loadBank(); papers.value = await api.papers(token.value); exams.value = await api.exams(token.value) } else if (isStudent.value) exams.value = await api.exams(token.value) }
function toggleQuestion(id: number) { selectedQuestions.value = selectedQuestions.value.includes(id) ? selectedQuestions.value.filter(value => value !== id) : [...selectedQuestions.value, id] }
async function createPaper() { error.value = ''; try { const score = paperForm.totalScore / selectedQuestions.value.length; if (!selectedQuestions.value.length) throw new Error('请至少选择一道题'); await api.createPaper(token.value, { ...paperForm, questions: selectedQuestions.value.map(questionId => ({ questionId, score })) }); selectedQuestions.value = []; papers.value = await api.papers(token.value); section.value = 'papers' } catch (reason) { error.value = (reason as Error).message } }
async function publishPaper(id: number) { try { await api.publishPaper(token.value, id); papers.value = await api.papers(token.value) } catch (reason) { error.value = (reason as Error).message } }
async function createExam() { try { await api.createExam(token.value, { name: examForm.name, paperId: Number(examForm.paperId), startAt: new Date(examForm.startAt).toISOString(), endAt: new Date(examForm.endAt).toISOString() }); exams.value = await api.exams(token.value); section.value = 'exams' } catch (reason) { error.value = (reason as Error).message } }
async function publishExam(id: number) { try { await api.publishExam(token.value, id); exams.value = await api.exams(token.value) } catch (reason) { error.value = (reason as Error).message } }
async function startExam(id: number) { error.value = ''; resultMessage.value = ''; try { submission.value = await api.startSubmission(token.value, id) } catch (reason) { error.value = (reason as Error).message } }
function choiceAnswer(questionId: number, key: string, multiple: boolean) { if (!multiple) { studentAnswers[questionId] = [key]; return } const current = Array.isArray(studentAnswers[questionId]) ? studentAnswers[questionId] as string[] : []; studentAnswers[questionId] = current.includes(key) ? current.filter(value => value !== key) : [...current, key] }
async function submitExam() { if (!submission.value || !window.confirm('交卷后不能修改，确认提交吗？')) return; try { const answers = submission.value.questions.map(question => ({ paperQuestionId: question.id, answerContent: studentAnswers[question.id] ?? null })); await api.saveAnswers(token.value, submission.value.id, answers); const result = await api.submit(token.value, submission.value.id); resultMessage.value = `交卷成功，客观题得分 ${result.objectiveScore} 分`; submission.value = null; exams.value = await api.exams(token.value) } catch (reason) { error.value = (reason as Error).message } }
onMounted(() => { if (user.value) void loadWorkspace() })
onUnmounted(() => window.clearInterval(clockTimer))
</script>

<template>
  <main v-if="!user" class="login-shell"><form class="login-card" @submit.prevent="login">
    <p class="eyebrow">SMART EXAM PLATFORM</p><h1>登录在线题库</h1>
    <label>账号<input v-model="username" autocomplete="username" required /></label><label>密码<input v-model="password" type="password" autocomplete="current-password" required /></label>
    <p v-if="error" class="error" role="alert">{{ error }}</p><button class="primary" :disabled="busy">{{ busy ? '登录中…' : '登录' }}</button><p class="hint">演示教师：teacher / ExamDemo123!</p>
  </form></main>
  <main v-else class="app-shell"><header><div><p class="eyebrow">SMART EXAM</p><h1>{{ isTeacher ? '教师工作台' : '学生考试中心' }}</h1></div><div class="account"><span>{{ user.displayName }} · {{ user.role }}</span><button @click="logout">退出</button></div></header>
    <p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="resultMessage" class="success">{{ resultMessage }}</p>
    <template v-if="isTeacher"><nav class="tabs"><button :class="{active:section==='bank'}" @click="section='bank'">题库</button><button :class="{active:section==='papers'}" @click="section='papers'">试卷</button><button :class="{active:section==='exams'}" @click="section='exams'">考试</button></nav>
    <template v-if="section==='bank'"><section class="toolbar panel">
      <select v-model="filters.type"><option value="">全部题型</option><option v-for="(label,key) in types" :key="key" :value="key">{{ label }}</option></select>
      <select v-model="filters.difficulty"><option value="">全部难度</option><option v-for="(label,key) in difficulties" :key="key" :value="key">{{ label }}</option></select>
      <select v-model="filters.knowledgePointId"><option value="">全部知识点</option><option v-for="point in points" :key="point.id" :value="String(point.id)">{{ point.name }}</option></select><button class="primary" @click="loadBank">筛选</button>
      <div class="point-add"><input v-model="pointName" placeholder="新知识点名称" /><button @click="addPoint">添加知识点</button></div>
    </section><section class="content-grid"><form class="panel editor" @submit.prevent="addQuestion"><h2>新增题目</h2>
      <label>题型<select v-model="form.type"><option v-for="(label,key) in types" :key="key" :value="key">{{ label }}</option></select></label><label>题干<textarea v-model="form.stem" required /></label>
      <div class="two"><label>难度<select v-model="form.difficulty"><option v-for="(label,key) in difficulties" :key="key" :value="key">{{ label }}</option></select></label><label>建议分值<input v-model.number="form.suggestedScore" type="number" min="0.1" step="0.1" /></label></div>
      <label>知识点<select v-model="form.knowledgePointId" required><option value="" disabled>请选择</option><option v-for="point in points" :key="point.id" :value="String(point.id)">{{ point.name }}</option></select></label>
      <label v-if="form.type.includes('CHOICE')">选项（每行：键|内容）<textarea v-model="form.optionsText" /></label><label>标准答案 <small v-if="form.type.includes('CHOICE')">（多项用英文逗号分隔）</small><input v-model="form.answer" required /></label><label>解析<textarea v-model="form.explanation" /></label><button class="primary">保存题目</button>
    </form><section class="panel list"><div class="list-title"><h2>题目列表</h2><span>{{ questions.length }} 道</span></div><article v-for="question in questions" :key="question.id"><div class="badges"><span>{{ types[question.type] }}</span><span>{{ difficulties[question.difficulty] }}</span><span>{{ question.knowledgePointName }}</span></div><h3>{{ question.stem }}</h3><p>{{ question.suggestedScore }} 分</p><button class="danger" @click="removeQuestion(question.id)">删除</button></article><p v-if="!questions.length" class="empty">暂无符合条件的题目</p></section></section></template>
    <section v-else-if="section==='papers'" class="content-grid"><form class="panel editor" @submit.prevent="createPaper"><h2>手动组卷</h2><label>试卷名称<input v-model="paperForm.name" required /></label><div class="two"><label>时长（分钟）<input v-model.number="paperForm.durationMinutes" type="number" min="1" required /></label><label>总分<input v-model.number="paperForm.totalScore" type="number" min="0.1" step="0.1" required /></label></div><p>已选 {{ selectedQuestions.length }} 题，将平均分配题目分值。</p><div class="question-picker"><label v-for="question in questions" :key="question.id"><input type="checkbox" :checked="selectedQuestions.includes(question.id)" @change="toggleQuestion(question.id)" />{{ question.stem }}（{{ question.suggestedScore }} 分建议）</label></div><button class="primary">保存试卷草稿</button></form><section class="panel list"><h2>试卷与预览</h2><article v-for="paper in papers" :key="paper.id"><div class="badges"><span>{{ paper.status }}</span><span>{{ paper.totalScore }} 分</span><span>{{ paper.durationMinutes }} 分钟</span></div><h3>{{ paper.name }}</h3><ol><li v-for="item in paper.questions" :key="item.id">{{ item.stem }}（{{ item.score }} 分）</li></ol><button v-if="paper.status==='DRAFT'" class="primary" @click="publishPaper(paper.id)">发布试卷</button></article><p v-if="!papers.length" class="empty">暂无试卷</p></section></section>
    <section v-else class="content-grid"><form class="panel editor" @submit.prevent="createExam"><h2>发布考试</h2><label>考试名称<input v-model="examForm.name" required /></label><label>已发布试卷<select v-model="examForm.paperId" required><option value="" disabled>请选择</option><option v-for="paper in papers.filter(item=>item.status==='PUBLISHED')" :key="paper.id" :value="String(paper.id)">{{ paper.name }}</option></select></label><label>开放时间<input v-model="examForm.startAt" type="datetime-local" required /></label><label>结束时间<input v-model="examForm.endAt" type="datetime-local" required /></label><button class="primary">创建考试草稿</button></form><section class="panel list"><h2>考试列表</h2><article v-for="exam in exams" :key="exam.id"><div class="badges"><span>{{ exam.status }}</span><span>{{ exam.paperName }}</span><span>{{ exam.totalScore }} 分</span></div><h3>{{ exam.name }}</h3><p>{{ new Date(exam.startAt).toLocaleString() }} — {{ new Date(exam.endAt).toLocaleString() }}</p><button v-if="exam.status==='DRAFT'" class="primary" @click="publishExam(exam.id)">发布考试</button></article><p v-if="!exams.length" class="empty">暂无考试</p></section></section></template>
    <template v-else-if="isStudent"><section v-if="!submission" class="panel list"><h2>可参加考试</h2><article v-for="exam in exams" :key="exam.id"><div class="badges"><span>{{ exam.submissionStatus || exam.status }}</span><span>{{ exam.durationMinutes }} 分钟</span><span>{{ exam.totalScore }} 分</span></div><h3>{{ exam.name }}</h3><p>{{ new Date(exam.startAt).toLocaleString() }} — {{ new Date(exam.endAt).toLocaleString() }}</p><button class="primary" :disabled="exam.submissionStatus==='SUBMITTED'" @click="startExam(exam.id)">{{ exam.submissionStatus==='SUBMITTED' ? '已交卷' : '进入考试' }}</button></article><p v-if="!exams.length" class="empty">暂无已发布考试</p></section><section v-else class="panel exam-sheet"><div class="list-title"><h2>在线答题</h2><strong class="countdown">剩余 {{ remaining }}</strong></div><article v-for="(question,index) in submission.questions" :key="question.id"><h3>{{ index+1 }}. {{ question.stem }}（{{ question.score }} 分）</h3><div v-if="question.type.includes('CHOICE')" class="options"><label v-for="option in question.options" :key="option.key"><input :type="question.type==='MULTIPLE_CHOICE'?'checkbox':'radio'" :name="String(question.id)" :checked="Array.isArray(studentAnswers[question.id]) && (studentAnswers[question.id] as string[]).includes(option.key)" @change="choiceAnswer(question.id,option.key,question.type==='MULTIPLE_CHOICE')" />{{ option.key }}. {{ option.content }}</label></div><div v-else-if="question.type==='TRUE_FALSE'" class="options"><label><input type="radio" :name="String(question.id)" :checked="studentAnswers[question.id]===true" @change="studentAnswers[question.id]=true" />正确</label><label><input type="radio" :name="String(question.id)" :checked="studentAnswers[question.id]===false" @change="studentAnswers[question.id]=false" />错误</label></div><textarea v-else v-model="studentAnswers[question.id] as string" placeholder="请输入答案" /></article><button class="primary" @click="submitExam">提交答卷</button></section></template>
    <section v-else class="panel"><h2>登录成功</h2><p>当前角色暂未开放此页面的业务功能。</p></section>
  </main>
</template>

<style>
:root{color:#17324d;background:#eef3f6;font-family:Inter,"PingFang SC","Microsoft YaHei",sans-serif}*{box-sizing:border-box}body{margin:0;min-width:320px;min-height:100vh}button,input,select,textarea{font:inherit}button{cursor:pointer;border:1px solid #cbd8df;border-radius:9px;background:white;padding:9px 14px;color:#24445e}button:disabled{cursor:not-allowed;opacity:.55}input,select,textarea{width:100%;border:1px solid #cbd8df;border-radius:9px;padding:10px;background:#fff;color:#17324d}textarea{min-height:82px;resize:vertical}label{display:grid;gap:7px;font-weight:600;color:#405c70}.eyebrow{margin:0 0 6px;color:#147d78;font-size:12px;font-weight:800;letter-spacing:.14em}h1,h2,h3,p{margin-top:0}.primary{background:#147d78;color:#fff;border-color:#147d78;font-weight:700}.error,.success{padding:10px 14px;border-radius:9px}.error{background:#fff0ee;color:#a63225}.success{background:#e7f6ee;color:#17653d}.login-shell{min-height:100vh;display:grid;place-items:center;padding:24px}.login-card{display:grid;gap:18px;width:min(440px,100%);padding:40px;border-radius:22px;background:#fff;box-shadow:0 18px 60px rgb(30 65 90 / 12%)}.login-card h1{font-size:34px}.hint{margin:0;color:#708697;font-size:13px}.app-shell{width:min(1280px,100%);margin:auto;padding:28px}.app-shell>header{display:flex;align-items:center;justify-content:space-between;margin-bottom:22px}.account,.tabs{display:flex;gap:14px;align-items:center}.tabs{margin-bottom:18px}.tabs button.active{background:#17324d;color:#fff}.panel{background:#fff;border:1px solid #dce6eb;border-radius:15px;padding:20px}.toolbar{display:grid;grid-template-columns:repeat(3,minmax(130px,1fr)) auto minmax(260px,1.4fr);gap:12px;margin-bottom:18px}.point-add{display:flex;gap:8px}.content-grid{display:grid;grid-template-columns:minmax(320px,420px) 1fr;gap:18px}.editor{display:grid;gap:15px;align-self:start}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.list-title{display:flex;justify-content:space-between}.countdown{color:#b13b31;font-size:20px}.list article{position:relative;padding:18px 90px 18px 0;border-top:1px solid #e5ecef}.list article h3{margin:10px 0 8px}.list article p{margin:0 0 10px;color:#708697}.badges{display:flex;gap:7px;flex-wrap:wrap}.badges span{padding:4px 8px;border-radius:99px;background:#e8f4f3;color:#116d68;font-size:12px}.danger{position:absolute;right:0;top:20px;color:#b13b31}.empty{color:#708697;text-align:center;padding:40px}.question-picker{display:grid;gap:8px;max-height:300px;overflow:auto}.question-picker label,.options label{display:flex;align-items:center;gap:8px;font-weight:400}.question-picker input,.options input{width:auto}.exam-sheet article{padding:20px 0;border-top:1px solid #e5ecef}.options{display:grid;gap:10px;margin:12px 0}@media(max-width:900px){.toolbar,.content-grid{grid-template-columns:1fr}.app-shell>header{align-items:flex-start}.account{flex-direction:column;align-items:flex-end}}@media(max-width:560px){.app-shell{padding:18px}.login-card{padding:28px 22px}.two{grid-template-columns:1fr}.account span{display:none}}
</style>
